{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket 'cloudtrail_logs' lacks a Public Access block, potentially exposing it to public access."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "Ensure all data stored in the S3 bucket have versioning enabled",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "HIGH",
      "explanation": "The S3 bucket 'cloudtrail_logs' does not have versioning enabled, which could lead to data loss or corruption."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"cloudtrail_logs\" {\n  bucket        = \"smart-city-parking-management-system-s3-cloudtrail-${random_string.cloudtrail_suffix.result}\"\n  force_destroy = true\n  versioning {\n    enabled = true\n  }\n}\n\nresource \"aws_s3_bucket_public_access_block\" \"cloudtrail_logs\" {\n  bucket = aws_s3_bucket.cloudtrail_logs.id\n\n  block_public_acls   = true\n  block_public_policy = true\n  ignore_public_acls  = true\n  restrict_public_buckets = true\n}",
  "fix_summary": "Added a Public Access block to the S3 bucket 'cloudtrail_logs' and enabled versioning on the bucket to prevent public exposure and data loss."
}
